const HTML_LIMIT=900_000;
const decode=s=>String(s||'').replace(/&(?:amp|lt|gt|quot|apos|nbsp);|&#(?:x[0-9a-f]+|\d+);/gi,x=>{const names={'&amp;':'&','&lt;':'<','&gt;':'>','&quot;':'"','&apos;':"'",'&nbsp;':' '};if(names[x.toLowerCase()])return names[x.toLowerCase()];const n=x.slice(2,-1);const code=n[0].toLowerCase()==='x'?parseInt(n.slice(1),16):parseInt(n,10);return code>0&&code<=0x10ffff?String.fromCodePoint(code):''});
const clean=s=>decode(String(s||'').replace(/<[^>]*>/g,' ')).replace(/\s+/g,' ').trim();
function attrs(tag){const a={};for(const m of tag.matchAll(/([\w:-]+)\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+))/g))a[m[1].toLowerCase()]=decode(m[2]??m[3]??m[4]);return a}
export function publicURL(value){let u;try{u=new URL(value.includes('://')?value:'https://'+value)}catch{throw new Error('Enter a valid public website URL.')}const h=u.hostname.toLowerCase();if(!['https:','http:'].includes(u.protocol)||u.username||u.password||u.port&&!['80','443'].includes(u.port)||!h.includes('.')||h.endsWith('.')||/^\d+(?:\.\d+){3}$/.test(h)||h.includes(':')||/\.(?:localhost|local|internal|test|example|invalid)$/.test(h)||h==='localhost'||h==='metadata.google.internal')throw new Error('Use a public website address, without credentials or a private network host.');u.hash='';return u}
async function readLimited(response,limit){if(Number(response.headers.get('content-length'))>limit)throw new Error('The source is too large to import.');const reader=response.body?.getReader();if(!reader)return new Uint8Array();let length=0;const pieces=[];while(true){const {value,done}=await reader.read();if(done)break;length+=value.length;if(length>limit){await reader.cancel();throw new Error('The source is too large to import.')}pieces.push(value)}const bytes=new Uint8Array(length);let offset=0;for(const p of pieces){bytes.set(p,offset);offset+=p.length}return bytes}
export async function retrieve(value,kind='html'){let u=publicURL(value);for(let i=0;i<5;i++){const r=await fetch(u.href,{redirect:'manual',signal:AbortSignal.timeout(10000),headers:{'User-Agent':'AstoriaBrandImporter/1.0','Accept':kind==='image'?'image/png,image/jpeg,image/webp':kind==='css'?'text/css':'text/html'}});if([301,302,303,307,308].includes(r.status)){const location=r.headers.get('location');if(!location)throw new Error('Website returned an invalid redirect.');u=publicURL(new URL(location,u).href);continue}if(!r.ok)throw new Error(`Website returned HTTP ${r.status}. It may block automated access.`);const mime=(r.headers.get('content-type')||'').split(';')[0].trim().toLowerCase();if(kind==='html'&&!/^(text\/html|application\/xhtml\+xml)$/.test(mime))throw new Error('This URL does not return a readable HTML website.');if(kind==='css'&&mime!=='text/css')throw new Error('Stylesheet is not readable CSS.');if(kind==='image'&&!['image/png','image/jpeg','image/webp','image/svg+xml'].includes(mime))throw new Error('Select a PNG, JPEG, WebP image, or SVG logo.');const bytes=await readLimited(r,kind==='image'?3_000_000:HTML_LIMIT);return {url:u.href,mime,bytes,text:kind==='image'?'':new TextDecoder().decode(bytes)}}throw new Error('Website redirects too many times.')}
function resolveURL(src,base){try{return publicURL(new URL(decode(src),base).href).href}catch{return null}}
export function parsePage(html,url){const source=html.replace(/<!--[^]*?-->/g,'').replace(/<(script|noscript|style)\b[^>]*>[^]*?<\/\1>/gi,' ');const meta={};for(const m of html.matchAll(/<meta\b[^>]*>/gi)){const a=attrs(m[0]);if(a.name||a.property)meta[(a.property||a.name).toLowerCase()]=a.content||''}const title=clean(html.match(/<title\b[^>]*>([^]*?)<\/title>/i)?.[1]);const snippets=[];for(const m of source.matchAll(/<(h[1-3]|p)\b[^>]*>([^]*?)<\/\1>/gi)){const text=clean(m[2]);if(text.length>=8&&text.length<=650&&!/cookie|privacy policy|all rights reserved|javascript/i.test(text)&&!snippets.some(s=>s.text===text))snippets.push({type:m[1].toLowerCase(),text,source:url})}const images=[];for(const m of html.matchAll(/<img\b[^>]*>/gi)){const a=attrs(m[0]),candidates=[a['data-src'],a['data-lazy-src'],a.src,a.srcset?.split(',').pop()?.trim().split(/\s+/)[0]].filter(Boolean);const src=candidates.map(x=>resolveURL(x,url)).find(Boolean);if(!src)continue;const description=[a.alt,a.class,a.id,src].join(' ');if(/tracking|pixel|spacer|spinner|payment|badge|icon-/i.test(description)||Number(a.width)>0&&Number(a.width)<45)continue;images.push({url:src,alt:clean(a.alt).slice(0,180),source:url,role:/logo|wordmark|brandmark/i.test(description)?'logo':'image'})}const og=meta['og:image']||meta['twitter:image'];if(og){const src=resolveURL(og,url);if(src)images.unshift({url:src,alt:meta['og:image:alt']||title,source:url,role:'hero'})}const css=[];for(const m of html.matchAll(/<link\b[^>]*>/gi)){const a=attrs(m[0]);if(a.rel?.includes('stylesheet')&&a.href){const link=resolveURL(a.href,url);if(link)css.push(link)}}const links=[];for(const m of source.matchAll(/<a\b[^>]*>/gi)){const a=attrs(m[0]);if(!a.href)continue;const link=resolveURL(a.href,url);if(link&&new URL(link).origin===new URL(url).origin&&/\/(?:about|our-story|story|products?|collections?)(?:\/|$)/i.test(new URL(link).pathname))links.push(link)}const inlineCSS=[...html.matchAll(/<style\b[^>]*>([^]*?)<\/style>/gi)].map(m=>m[1]).join('\n')+'\n'+[...html.matchAll(/\bstyle\s*=\s*["']([^"']*)["']/gi)].map(m=>m[1]).join('\n');return {url,title,description:clean(meta.description||meta['og:description']),brandName:clean(meta['og:site_name']),snippets:snippets.slice(0,35),images,css:css.slice(0,2),links:[...new Set(links)].slice(0,2),inlineCSS}}
export function palette(css){const counts=new Map();for(const m of css.matchAll(/#[0-9a-f]{6}\b|#[0-9a-f]{3}\b|rgba?\(\s*\d+\s*,\s*\d+\s*,\s*\d+(?:\s*,\s*[\d.]+)?\s*\)/gi)){let c=m[0].toLowerCase();if(c.startsWith('rgb')){const n=c.match(/\d+/g).slice(0,3).map(Number);if(n.some(x=>x>255))continue;c='#'+n.map(x=>x.toString(16).padStart(2,'0')).join('')}if(c.length===4)c='#'+c.slice(1).split('').map(x=>x+x).join('');counts.set(c,(counts.get(c)||0)+1)}return [...counts].sort((a,b)=>b[1]-a[1]).slice(0,10).map(([hex,count])=>({hex,count,method:'Stylesheet color frequency; review before use'}))}
export async function importBrand(value){const home=await retrieve(value);const pages=[parsePage(home.text,home.url)],warnings=[];const extras=await Promise.allSettled(pages[0].links.map(u=>retrieve(u)));extras.forEach(r=>{if(r.status==='fulfilled')pages.push(parsePage(r.value.text,r.value.url));else warnings.push('An additional brand page could not be read.')});const styles=await Promise.allSettled(pages[0].css.map(u=>retrieve(u,'css')));const css=pages.map(p=>p.inlineCSS).join('\n')+styles.filter(r=>r.status==='fulfilled').map(r=>r.value.text).join('\n');if(styles.some(r=>r.status==='rejected'))warnings.push('Some stylesheet colors could not be read.');const images=[...new Map(pages.flatMap(p=>p.images).map(i=>[i.url,i])).values()].sort((a,b)=>(a.role==='logo'?-1:b.role==='logo'?1:0)).slice(0,18);const snippets=[...new Map(pages.flatMap(p=>p.snippets).map(s=>[s.text,s])).values()].slice(0,45);const h=snippets.find(s=>s.type==='h1');if(!h&&!snippets.length)warnings.push('Little readable copy was found. This website may render its content with JavaScript.');const base=pages[0],headline=h?.text||base.title,description=base.description||snippets.find(s=>s.type==='p')?.text||'';const copy=snippets.map(s=>s.text).join(' '),short=snippets.length?snippets.filter(s=>s.text.split(' ').length<12).length/snippets.length:0;const tone=/\byou\b|\byour\b/i.test(copy)?'Direct and reader-focused':short>.5?'Concise and headline-led':'Descriptive and explanatory';return {source:home.url,importedAt:new Date().toISOString(),pages:pages.map(p=>({url:p.url,title:p.title})),brandName:base.brandName||'',headline,description,snippets,images,colors:palette(css),suggested:{positioning:description||headline,voice:`${tone}. Suggested from the source copy; review for fit.`,pillars:snippets.filter(s=>s.type==='h2').slice(0,3).map(s=>s.text).join('\n'),headline},warnings:[...new Set([...warnings,'Reads public HTML and up to two related pages. It does not execute website JavaScript.','Tone is a rule-based suggestion; existing copy and imagery remain identifiable source material.'])]}}


const responses=new Map();
function json(data,status=200){return new Response(JSON.stringify(data),{status,headers:{'content-type':'application/json','cache-control':'no-store','x-content-type-options':'nosniff'}})}
export default {async fetch(request){const u=new URL(request.url);if(u.pathname.startsWith('/api/')){try{const origin=request.headers.get('origin');if(origin&&origin!==u.origin)return json({error:'Requests must originate from Astoria.'},403);if(u.pathname==='/api/brand-import'&&request.method==='POST'){const ip=request.headers.get('cf-connecting-ip')||'local',now=Date.now(),last=responses.get(ip)||0;if(now-last<1500)return json({error:'Please wait a moment before importing again.'},429);responses.set(ip,now);if(responses.size>1000)responses.clear();if(Number(request.headers.get('content-length'))>8000)return json({error:'Request is too large.'},413);const body=await request.json();if(typeof body.url!=='string'||body.url.length>2000)return json({error:'Enter a website URL.'},400);return json(await importBrand(body.url))}if(u.pathname==='/api/brand-image'&&request.method==='GET'){const result=await retrieve(u.searchParams.get('url')||'','image');return new Response(result.bytes,{headers:{'content-type':result.mime,'cache-control':'private, max-age=3600','x-content-type-options':'nosniff','content-security-policy':"default-src 'none'; sandbox"}})}return json({error:'Endpoint not found.'},404)}catch(e){return json({error:e.name==='TimeoutError'?'Website timed out. Try another public page.':e.message||'Website could not be imported.'},422)}}const key=u.pathname==='/'?'/index.html':u.pathname;const item=STATIC_FILES[key];if(!item)return new Response('Not found',{status:404});return new Response(item.body,{headers:{'content-type':item.type,'cache-control':'no-cache','x-content-type-options':'nosniff'}})}};
